## ---- sol-20-setup ----
source("_common.R")
library(tidypm)
R  <- as_xts_pm(sim_class_returns_monthly, date, class, return)
rf <- sim_riskfree_monthly$return
eq <- sim_assets[sim_assets$asset_class == "equity", ]
A  <- as_xts_pm(sim_asset_returns_monthly[sim_asset_returns_monthly$asset %in% eq$asset_id, ],
                date, asset, return)[, eq$asset_id]
region  <- setNames(eq$region, eq$asset_id)
regions <- c("US", "EU", "UK", "CH", "JP")
d <- zoo::index(A); X <- zoo::coredata(A); N <- ncol(X)
cap_w <- sim_marketcap_weekly[sim_marketcap_weekly$asset %in% eq$asset_id, ] |>
  tidyr::pivot_wider(names_from = asset, values_from = market_cap) |> dplyr::arrange(date)
wk1 <- min(sim_asset_returns_weekly$date)
Cap <- as.matrix(cap_w[findInterval(c(wk1 - 1, d[-length(d)]), cap_w$date), eq$asset_id])
stopifnot(!anyNA(Cap), identical(colnames(Cap), colnames(X)))
cap_w_of <- function(t, j) Cap[t, j] / sum(Cap[t, j])

# The chapter's construction and helpers, repeated so that this fragment runs on its own.
esg_start <- function(assets, dist = function(n) stats::rnorm(n, mean = 4, sd = 1.2),
                      seed = 1602, scale = c(1, 7)) {
  set.seed(seed)
  setNames(pmin(pmax(dist(length(assets)), scale[1]), scale[2]), assets)
}
esg_levels <- function(start, changes = sim_esg_changes_quarterly, dates = d, scale = c(1, 7)) {
  L <- matrix(start, length(dates), length(start), byrow = TRUE, dimnames = list(NULL, names(start)))
  for (k in seq_len(nrow(changes))) {
    from <- match(TRUE, dates > changes$date[k])
    if (is.na(from)) next
    L[from:nrow(L), changes$asset[k]] <- L[from:nrow(L), changes$asset[k]] + changes$esg_change[k]
  }
  pmin(pmax(L, scale[1]), scale[2])
}
s0 <- esg_start(eq$asset_id); L <- esg_levels(s0); t1 <- 121L; W <- 120L
shrunk <- function(X) {
  S <- corpcor::cov.shrink(X, verbose = FALSE)
  matrix(as.numeric(S), ncol(X), ncol(X), dimnames = list(colnames(X), colnames(X)))
}
te_of    <- function(w, b, S) sqrt(12 * as.numeric(t(w - b) %*% S %*% (w - b)))
p_vol    <- function(w, S)    sqrt(12 * as.numeric(t(w) %*% S %*% w))
score_of <- function(w, s)    sum(w * s) / sum(w)
bottom_of <- function(s, q = 0.2)
  unlist(lapply(split(names(s), region[names(s)]), function(j)
    j[rank(s[j], ties.method = "first") <= ceiling(q * length(j))]), use.names = FALSE)
screen_w <- function(b, excl) {
  w <- b; w[excl] <- 0
  for (g in unique(region[names(b)])) {
    j <- names(b)[region[names(b)] == g]
    if (sum(w[j]) > 0) w[j] <- w[j] * sum(b[j]) / sum(w[j])
  }
  w
}
bic_B <- function(s, floor, groups = unique(region[names(s)])) {
  B <- sapply(groups, function(g) (s - floor) * (region[names(s)] == g)); rownames(B) <- names(s); B
}
min_te <- function(S, b, cap = pmax(0.10, b), B = NULL, lower = NULL, budget, mu = NULL) {
  n <- length(b); G <- sapply(names(budget), function(g) as.numeric(region[names(b)] == g))
  Amat <- cbind(G, diag(n), -diag(n)); bvec <- c(unname(budget), rep(0, n), -cap)
  k <- if (is.null(B)) 0L else NCOL(B)
  if (k > 0) { Amat <- cbind(Amat, B); bvec <- c(bvec, lower) }
  dvec <- if (is.null(mu)) 2 * as.numeric(S %*% b) else rep(0, n)
  sol  <- quadprog::solve.QP(2 * S, dvec, Amat, bvec, meq = length(budget))
  w <- pmax(sol$solution, 0); w <- setNames(w / sum(w), names(b))
  attr(w, "lambda") <- if (k > 0) sol$Lagrangian[ncol(Amat) - k + seq_len(k)] else numeric(0)
  w
}
shrinkage_moments <- function(R, portfolio) {
  S <- shrunk(zoo::coredata(R)); list(mu = colMeans(R), sigma = S, m3 = NULL, m4 = NULL)
}
# the implementation's sleeve: five equal regional budgets at the register's start
bench_of <- function(t, budget) {
  b <- setNames(numeric(N), colnames(X))
  for (g in names(budget)) { j <- names(region)[region == g]; b[j] <- budget[[g]] * cap_w_of(t, j) }
  b
}
budget <- setNames(rep(0.2, length(regions)), regions)
b <- bench_of(t1, budget); S <- shrunk(X[(t1 - W):(t1 - 1L), ]); s <- L[t1, ]
grp <- split(seq_len(N), region[colnames(X)]); gbud <- budget[names(grp)]
# the application's sleeve: the policy's equity split, recomputed
Re <- R - rf; S16 <- stats::cov(Re); mu16 <- colMeans(Re)
qp <- function(S, a) {
  n <- ncol(S)
  w <- quadprog::solve.QP(2 * S, rep(0, n), cbind(a, diag(n)), c(1, rep(0, n)), meq = 1)$solution
  w <- pmax(w, 0); setNames(w / sum(w), colnames(S))
}
kind <- sub(".*_", "", colnames(Re)); sl <- split(colnames(Re), kind)
v <- lapply(names(sl), function(k) {
  a <- sl[[k]]; if (length(a) == 1L) return(setNames(1, a))
  qp(S16[a, a], if (k == "equity") mu16[a] else rep(1, length(a)))
}); names(v) <- names(sl)
eq_split <- v$equity[v$equity > 1e-6]; eq_split <- eq_split / sum(eq_split)
budget_app <- setNames(as.numeric(eq_split), sub("_equity$", "", names(eq_split)))
js  <- names(region)[region %in% names(budget_app)]
oos <- seq.int(t1, nrow(X))
bench_app <- function(t) {
  b <- setNames(numeric(length(js)), js)
  for (g in names(budget_app)) { j <- js[region[js] == g]; b[j] <- budget_app[[g]] * cap_w_of(t, j) }
  b
}
path_turnover <- function(Wm, Xj) {
  drifted <- Wm * (1 + Xj) / (1 + rowSums(Wm * Xj))
  mean(rowSums(abs(Wm[-1, ] - drifted[-nrow(Wm), ]))) / 2 * 12
}
te <- function(a) stats::sd(a) * sqrt(12); ir <- function(a) mean(a) / stats::sd(a) * sqrt(12)

# ===== Exercise 1 =====

## ---- sol-20-ex1 ----
attainable <- function(s, b, budget, cap = pmax(b, 0.10)) {   # the highest rating the cap and budgets allow; pmax keeps b's names
  w <- setNames(numeric(length(b)), names(b))
  for (g in names(budget)) {
    j <- names(b)[region[names(b)] == g]; j <- j[order(s[j], decreasing = TRUE)]; left <- budget[[g]]
    for (i in j) { w[i] <- min(cap[i], left); left <- left - w[i]; if (left <= 0) break }
  }
  score_of(w, s)
}
runs <- lapply(oos, function(t) {
  b_t <- bench_app(t); s_t <- L[t, js]; S_t <- shrunk(X[(t - W):(t - 1L), js])
  f_abs <- 5; f_rel <- min(score_of(b_t, s_t) + 0.5, attainable(s_t, b_t, budget_app) - 0.05)
  w_abs <- min_te(S_t, b_t, B = s_t, lower = f_abs, budget = budget_app)
  w_rel <- min_te(S_t, b_t, B = s_t, lower = f_rel, budget = budget_app)
  list(benchmark = b_t, absolute = w_abs, relative = w_rel,
       binds_abs = attr(w_abs, "lambda")[1] > 1e-12, binds_rel = attr(w_rel, "lambda")[1] > 1e-12)
})
Wm <- lapply(c("benchmark", "absolute", "relative"), function(f)
  t(vapply(runs, function(r) as.numeric(r[[f]]), numeric(length(js)))))
names(Wm) <- c("benchmark", "absolute", "relative")
r_s <- lapply(Wm, function(M) rowSums(M * X[oos, js]))
ex1 <- tibble::tibble(floor = c("absolute, 5", "relative, benchmark + 0.5"),
  te = c(te(r_s$absolute - r_s$benchmark), te(r_s$relative - r_s$benchmark)),
  ir = c(ir(r_s$absolute - r_s$benchmark), ir(r_s$relative - r_s$benchmark)),
  turnover = c(path_turnover(Wm$absolute, X[oos, js]), path_turnover(Wm$relative, X[oos, js])),
  months_binding = c(sum(vapply(runs, `[[`, logical(1), "binds_abs")), sum(vapply(runs, `[[`, logical(1), "binds_rel"))))
stopifnot(ex1$months_binding[2] == length(oos), ex1$te[2] > ex1$te[1], ex1$turnover[2] > ex1$turnover[1])
ex1

# ===== Exercise 2 =====

## ---- sol-20-ex2 ----
s_narrow <- esg_levels(esg_start(eq$asset_id, dist = function(n) stats::rnorm(n, 4, 0.6)))[t1, ]
top2 <- function(s) vapply(names(grp), function(g) mean(sort(s[grp[[g]]], decreasing = TRUE)[1:2]), numeric(1))
s_max_wide <- sum(gbud * top2(s)); s_max_narrow <- sum(gbud * top2(s_narrow))
floors <- seq(4, 6, by = 0.5); floors <- floors[floors < min(s_max_wide, s_max_narrow)]
cost <- function(sv, f) { w <- min_te(S, b, B = sv, lower = f, budget = gbud)
                          c(te = te_of(w, b, S), lambda = attr(w, "lambda")[1]) }
tibble::tibble(floor = floors,
               te_wide   = vapply(floors, function(f) cost(s, f)[["te"]], numeric(1)),
               te_narrow = vapply(floors, function(f) cost(s_narrow, f)[["te"]], numeric(1)),
               lambda_wide   = vapply(floors, function(f) cost(s, f)[["lambda"]], numeric(1)),
               lambda_narrow = vapply(floors, function(f) cost(s_narrow, f)[["lambda"]], numeric(1)))

# ===== Exercise 3 =====

## ---- sol-20-ex3 ----
gmv_lo <- function(S) {
  n <- ncol(S)
  w <- quadprog::solve.QP(2 * S, rep(0, n), cbind(rep(1, n), diag(n)), c(1, rep(0, n)), meq = 1)$solution
  w <- pmax(w, 0); setNames(w / sum(w), colnames(S))
}
screened_mv <- function(excl) {
  keep <- setdiff(colnames(X), excl)
  w <- setNames(numeric(N), colnames(X)); w[keep] <- gmv_lo(S[keep, keep]); w
}
binding <- function(excl) {                        # excluded names with a negative multiplier
  w <- screened_mv(excl); delta <- as.numeric(S %*% w) - as.numeric(t(w) %*% S %*% w)
  names(delta) <- colnames(X); sum(delta[excl] < -1e-7)
}
excl <- bottom_of(s)
ub <- setNames(rep(1, N), colnames(X)); ub[excl] <- 0          # the exclusion as a box, by name
spec_box <- portfolio.spec(assets = colnames(X)) |>
  add.constraint(type = "full_investment") |>
  add.constraint(type = "box", min = 0, max = ub) |>
  add.objective(type = "risk", name = "var")
w_box <- extractWeights(optimize.portfolio(A[(t1 - W):(t1 - 1L), ], spec_box,
                                           optimize_method = "ROI", momentFUN = shrinkage_moments))[colnames(X)]
w_mvx <- screened_mv(excl)
stopifnot(all(w_box[excl] < 1e-8), max(abs(w_box - w_mvx)) < 1e-5)
excl10 <- bottom_of(s, q = 0.1)
c(agree_to = max(abs(w_box - w_mvx)), binding_fifth = binding(excl), of = length(excl),
  binding_tenth = binding(excl10), of = length(excl10))

# ===== Exercise 4 =====

## ---- sol-20-ex4 ----
z0 <- (s0 - 4) / 1.2
second_rater <- function(rho, seed)
  esg_start(eq$asset_id, seed = seed, dist = function(n) 4 + 1.2 * (rho * z0 + sqrt(1 - rho^2) * stats::rnorm(n)))
w_1 <- min_te(S, b, B = s, lower = 5, budget = gbud)
gap <- t(vapply(1:20, function(sd) {
  s2  <- esg_levels(second_rater(0.54, sd))[t1, ]
  w_2 <- min_te(S, b, B = s2, lower = 5, budget = gbud)
  c(active_share = sum(abs(w_1 - w_2)) / 2, te_between = te_of(w_1, w_2, S),
    te_each = te_of(w_2, b, S))
}, numeric(3)))
round(colMeans(gap), 4)
